% Optional MTEX comparison. Supply a CTF and its .orientation.json sidecar
% generated by ebsd_autoplot.mtex.export_roi_ctf. No nominal lattice values
% or phase ids are embedded in this script.
% The sidecar records Euler units, phase mapping, ROI and preserved source
% rotations. Confirm the instrument reference frame before interpreting fits.

scriptDir = fileparts(mfilename('fullpath'));
ctfFile = fullfile(scriptDir,'verification_roi.ctf'); % set this to the exported ROI path
assert(isfile(ctfFile),'Pass an exported verification_roi.ctf file');
sidecar = strrep(ctfFile,'.ctf','.orientation.json');
assert(isfile(sidecar),'The CTF orientation sidecar is required');
meta = jsondecode(fileread(sidecar));
assert(strcmp(meta.ctf_euler_unit,'degree'),'Expected CTF Euler degrees');
phaseKeys = fieldnames(meta.phase_id_mapping);
phaseIds = cellfun(@str2double,phaseKeys);
[~,order] = sort(phaseIds);
phaseKeys = phaseKeys(order);
CS = {'notIndexed'};
for k = 1:numel(phaseKeys)
  spec = meta.phase_id_mapping.(phaseKeys{k});
  lattice = spec.lattice_parameters;
  assert(~isempty(lattice),'Measured lattice parameters missing for phase %s',spec.name);
  dims = [lattice.a lattice.b lattice.c];
  angles = [lattice.alpha_deg lattice.beta_deg lattice.gamma_deg];
  if spec.space_group == 194
    symmetry = '6/mmm';
  elseif spec.space_group == 229
    symmetry = 'm-3m';
  else
    error('Unsupported V3 phase space group %d',spec.space_group);
  end
  CS{end+1} = crystalSymmetry(symmetry,dims,angles, ...
      'mineral',spec.name); %#ok<SAGROW>
end

setMTEXpref('xAxisDirection','east');
setMTEXpref('zAxisDirection','outOfPlane');
ebsd = EBSD.load(ctfFile,CS,'interface','ctf','convertEuler2SpatialReferenceFrame');
[grains,ebsd] = calcGrains(ebsd,'threshold',1.5*degree,'removeQuadruplePoints');
job = parentGrainReconstructor(ebsd,grains);
job.p2c = orientation.Burgers(job.csParent,job.csChild);
job.calcVariantGraph('threshold',1.5*degree);
job.clusterVariantGraph('numIter',3);
job.calcParentFromVote;
figure; plot(job.parentGrains,'ipfDirection',zvector);
title('MTEX prior-beta candidate — inspect fit, coverage and frame settings');
out = fullfile(fileparts(ctfFile),'MTEX_prior_beta_candidate.png');
saveas(gcf,out);
fprintf('MTEX candidate plot: %s\n',out);
fprintf('Source orientation metadata: %s\n',sidecar);
% Compare parent-grain orientations and boundaries against Python outputs
% only after reconciling MTEX thresholds, coordinate frames and phase names.
